import{_ as s,o as e,c as a,a2 as o}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"PHP Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"dev/php-compatibility.md","filePath":"dev/php-compatibility.md"}'),t={name:"dev/php-compatibility.md"};function l(n,i,c,d,p,r){return e(),a("div",null,[...i[0]||(i[0]=[o(`<h1 id="php-compatibility" tabindex="-1">PHP Compatibility <a class="header-anchor" href="#php-compatibility" aria-label="Permalink to &quot;PHP Compatibility&quot;">​</a></h1><p>This repository keeps two layers of PHP compatibility validation:</p><ul><li>Static compatibility checks for PHP <code>8.0</code> through <code>8.5</code>.</li><li>WordPress smoke tests for the PHP and WordPress combinations we currently support or monitor.</li></ul><h2 id="policy-snapshot" tabindex="-1">Policy snapshot <a class="header-anchor" href="#policy-snapshot" aria-label="Permalink to &quot;Policy snapshot&quot;">​</a></h2><p>Validated on May 21, 2026.</p><ul><li>Primary support: PHP <code>8.2</code>, <code>8.3</code>, and <code>8.4</code>.</li><li>Experimental monitoring: PHP <code>8.5</code>.</li><li>Stable WordPress gate: <code>WordPress 7.0</code> on PHP <code>8.2</code>, <code>8.3</code>, and <code>8.4</code>.</li><li>Experimental WordPress gate: <code>WordPress 7.0</code> on PHP <code>8.5</code>.</li><li>Backward-compatibility coverage: <code>WordPress 6.6</code> on PHP <code>8.0</code> and <code>8.1</code>.</li></ul><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><ul><li>Static checks: <code>.github/workflows/php-compat.yml</code></li><li>WordPress smoke tests: <code>.github/workflows/wordpress-smoke.yml</code></li></ul><h2 id="how-php-8-5-is-covered" tabindex="-1">How PHP 8.5 is covered <a class="header-anchor" href="#how-php-8-5-is-covered" aria-label="Permalink to &quot;How PHP 8.5 is covered&quot;">​</a></h2><ul><li><code>phpcs-compat.xml.dist</code> runs PHPCompatibilityWP against the plugin source with <code>testVersion</code> set to PHP <code>8.0-8.5</code>.</li><li><code>.github/workflows/php-compat.yml</code> runs that PHPCompatibilityWP ruleset as the repository&#39;s static PHP compatibility gate.</li><li><code>.github/workflows/wordpress-smoke.yml</code> includes one experimental PHP <code>8.5</code> smoke job for <code>WordPress 7.0</code>.</li><li><code>scripts/wordpress-smoke.sh</code> honors <code>WP_CLI_PHP</code>, so the same runtime smoke can be executed against PHP <code>8.5</code> locally.</li><li>Stable <code>wp-cli</code> support for PHP <code>8.5</code> is still planned upstream. That mismatch is why PHP <code>8.5</code> remains experimental in this repository&#39;s CI policy.</li></ul><h2 id="local-commands" tabindex="-1">Local commands <a class="header-anchor" href="#local-commands" aria-label="Permalink to &quot;Local commands&quot;">​</a></h2><p>Run the static PHP compatibility checks locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-interaction</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-progress</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefer-dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vendor/bin/phpcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --standard=phpcs-compat.xml.dist</span></span></code></pre></div><p>Run the WordPress smoke test locally with an explicit PHP runtime:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_CLI_PHP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/homebrew/opt/php@8.4/bin/php</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_DB_HOST=localhost </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_DB_NAME=wordpress </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_DB_USER=your-user </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_DB_PASSWORD=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WP_VERSION=7.0 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/wordpress-smoke.sh</span></span></code></pre></div><p>The smoke script now honors <code>WP_CLI_PHP</code> directly, which avoids Homebrew <code>wp</code> defaulting to the active <code>php</code> binary in <code>PATH</code>. The repository itself is currently clean under PHP <code>8.5</code>, but <code>wp-cli</code> 2.12.0 still emits third-party deprecation noise there, so PHP <code>8.5</code> remains an experimental runtime line.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li>PHPCompatibilityWP static checks are green for PHP <code>8.0</code> through <code>8.5</code>.</li><li>Local WordPress smoke on PHP <code>8.5</code> passes, but still logs third-party deprecations from <code>wp-cli</code> and its bundled libraries.</li><li>Keep PHP <code>8.5</code> experimental in CI until those third-party logs stop obscuring runtime signal.</li></ul>`,18)])])}const P=s(t,[["render",l]]);export{k as __pageData,P as default};
